def merge(intervals):
    """Merge overlapping or touching [start, end] intervals without modifying input."""
    ordered = sorted((list(interval) for interval in intervals), key=lambda x: (x[0], x[1]))
    merged = []

    for start, end in ordered:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        elif end > merged[-1][1]:
            merged[-1][1] = end

    return merged
